solution.solution.js:
function inStockNames(products) {
  return products.filter(p => p.stock > 0).map(p => p.name);
}

function stockValue(products) {
  return products.reduce((sum, p) => sum + p.price * p.stock, 0);
}

function cheapestFirst(products) {
  return [...products].sort((a, b) =>
    a.price - b.price || a.name.toLowerCase().localeCompare(b.name.toLowerCase()));
}

function allTags(products) {
  const tags = [];
  for (const tag of products.flatMap(p => p.tags)) {
    if (!tags.includes(tag)) tags.push(tag);
  }
  return tags.sort();
}

unitTests:
const shop = () => [
  { name: "Mug", price: 8, stock: 3, tags: ["kitchen", "gift"] },
  { name: "lamp", price: 25, stock: 0, tags: ["home"] },
  { name: "Candle", price: 8, stock: 10, tags: ["home", "gift"] },
  { name: "Pen", price: 2, stock: 50, tags: [] },
];

test("filter then map", () => {
  checkEq(inStockNames(shop()), ["Mug", "Candle", "Pen"]);
  checkEq(inStockNames([]), []);
});

test("reduce to a total", () => {
  checkEq(stockValue(shop()), 24 + 0 + 80 + 100);
  checkEq(stockValue([]), 0);
});

test("sort a copy by two keys", () => {
  const items = shop();
  const sorted = cheapestFirst(items);
  checkEq(sorted.map(p => p.name), ["Pen", "Candle", "Mug", "lamp"]);
  checkEq(items[0].name, "Mug");
});

test("unique sorted tags", () => {
  checkEq(allTags(shop()), ["gift", "home", "kitchen"]);
  checkEq(allTags([]), []);
});

